// ---------- Комментарии к постам канала ----------
const cmOut = (c, ix) => { const u = ix().get(c.userId); return { id: c.id, userId: c.userId, text: c.text, at: c.at, u: u ? userLite(u) : { id: c.userId, username: 'Удалённый аккаунт', avatar: '' } }; };
// Пост ленты канала, к которому участник может писать комментарии
function postFor(req, res) {
    const messages = read(F.messages), msg = messages.find(m => m.id === req.params.messageId);
    const chat = msg && chatOf(msg.chatId);
    if (!msg || !chat || chat.type !== 'channel' || chat.open || !chat.members.includes(req.uid)) { res.status(404).json({ error: 'Пост не найден' }); return null; }
    return { messages, msg, chat };
}
app.get('/api/messages/:messageId/comments', (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const ix = lazyIdx(), list = p.msg.comments || [];
    res.json({ count: list.length, comments: list.slice(-200).map(c => cmOut(c, ix)) });
});
app.post('/api/messages/:messageId/comments', async (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const text = String(req.body.text || '').trim().slice(0, 500);
    if (!text) return res.status(400).json({ error: 'Напишите комментарий' });
    const c = { id: crypto.randomUUID(), userId: req.uid, text, at: new Date().toISOString() };
    p.msg.comments = (p.msg.comments || []).concat(c).slice(-1000);
    write(F.messages, p.messages);
    const ix = lazyIdx(), o = outMsg(p.msg, p.chat, ix), out = cmOut(c, ix);
    sendTo(p.chat.members, { type: 'comments', data: { chatId: p.chat.id, messageId: p.msg.id, cc: o.cc, ca: o.ca || [], comment: out } });
    await persist();
    res.json({ success: true, comment: out });
});
app.delete('/api/messages/:messageId/comments/:cid', async (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const c = (p.msg.comments || []).find(x => x.id === req.params.cid);
    if (!c) return res.status(404).json({ error: 'Комментарий не найден' });
    if (c.userId !== req.uid && p.chat.creator !== req.uid) return res.status(403).json({ error: 'Нельзя удалить чужой комментарий' });
    p.msg.comments = p.msg.comments.filter(x => x !== c);
    write(F.messages, p.messages);
    const o = outMsg(p.msg, p.chat);
    sendTo(p.chat.members, { type: 'comments', data: { chatId: p.chat.id, messageId: p.msg.id, cc: o.cc, ca: o.ca || [], removed: c.id } });
    await persist();
    res.json({ success: true });
});

// Реакция на сообщение: одна на человека; тот же смайл ещё раз — снять
app.post('/api/messages/:messageId/react', async (req, res) => {
    const me = req.uid, emoji = String(req.body.emoji || '');
    if (!REACTIONS.includes(emoji)) return res.status(400).json({ error: 'Такой реакции нет' });
    const messages = read(F.messages), msg = messages.find(m => m.id === req.params.messageId);
    const chat = msg && chatOf(msg.chatId);
    if (!msg || !chat || !chat.members.includes(me)) return res.status(404).json({ error: 'Сообщение не найдено' });
    if (chat.type === 'direct') {
        const other = chat.members.find(i => i !== me);
        if (other === BOT_ID || (other && blockedEither(me, other))) return res.status(400).json({ error: 'Нельзя поставить реакцию' });
    }
    const r = msg.reactions = msg.reactions || {};
    const had = (r[emoji] || []).includes(me);
    for (const e of Object.keys(r)) { r[e] = r[e].filter(id => id !== me); if (!r[e].length) delete r[e]; }
    if (!had) (r[emoji] = r[emoji] || []).push(me);
    if (!Object.keys(r).length) delete msg.reactions;
    write(F.messages, messages);
    sendTo(chat.members, { type: 'reaction', data: { chatId: msg.chatId, messageId: msg.id, reactions: msg.reactions || {} } });
    await persist();
    res.json({ success: true });
});

// ---------- Удаление чатов ----------
// Личный: «у меня» скрывает историю только для меня, both=1 удаляет у обоих.
// Группа: выйти (создатель с both=1 удаляет для всех). Канал: автор удаляет, подписчик отписывается.
app.delete('/api/chats/:chatId', async (req, res) => {
    const me = req.uid, both = req.query.both === '1';
    const chats = read(F.chats), chat = chats.find(c => String(c.id) === req.params.chatId);
    if (!chat || !chat.members.includes(me)) return res.status(404).json({ error: 'Чат не найден' });
    const members = [...chat.members];
    const dropAll = () => {
        write(F.chats, chats.filter(c => c !== chat));
        write(F.messages, read(F.messages).filter(m => m.chatId !== chat.id));
    };
    const leave = () => {
        chat.members = chat.members.filter(id => id !== me);
        if (chat.members.length) write(F.chats, chats); else dropAll();
    };
    if (chat.type === 'direct') {
        if (both) dropAll();
        else { chat.cleared = chat.cleared || {}; chat.cleared[me] = new Date().toISOString(); write(F.chats, chats); }
    } else if (chat.type === 'group') {
        if (both && chat.creator === me) dropAll(); else leave();
    } else if (chat.creator === me) dropAll();
    else leave();
    sendTo(members, { type: 'chat' });
    await persist();
    res.json({ success: true });
});

// ---------- Админ-панель (доступна только аккаунту с юзернеймом ADMIN_HANDLE) ----------
const ADMIN_HANDLES = ['saimon'];
const ADMIN_HANDLE = 'saimon'; // главный (нельзя заблокировать/удалить)
const isAdminUid = uid => { const u = read(F.users).find(x => x.id === uid); return !!u && ADMIN_HANDLES.includes(u.handle); };
const adminOnly = (req, res, next) => isAdminUid(req.uid) ? next() : res.status(403).json({ error: 'Нет доступа' });

app.get('/api/admin/channels', adminOnly, (req, res) => {
    const users = read(F.users);
    res.json(read(F.chats).filter(c => c.type === 'channel').map(c => ({
        id: c.id, name: c.name, handle: c.handle || '', members: (c.members || []).length,
        creator: ((users.find(u => u.id === c.creator)) || {}).username || '—'
    })));
});

app.delete('/api/admin/channels/:id', adminOnly, async (req, res) => {
    const chats = read(F.chats), ch = chats.find(c => String(c.id) === req.params.id && c.type === 'channel');
    if (!ch) return res.status(404).json({ error: 'Канал не найден' });
    const members = [...(ch.members || [])];
    write(F.chats, chats.filter(c => c !== ch));
    write(F.messages, read(F.messages).filter(m => m.chatId !== ch.id));
    sendTo(members, { type: 'chat' });
    await persist();
    res.json({ success: true });
});

app.get('/api/admin/users', adminOnly, (req, res) => {
    const s = String(req.query.q || '').toLowerCase().replace(/^@/, '');
    res.json(read(F.users)
        .filter(u => !u.fake && !u.bot && !u.banned && !ADMIN_HANDLES.includes(u.handle) && (
            u.username.toLowerCase().includes(s) ||
            (u.handles || [u.handle]).some(h => (h || '').includes(s))))
        .slice(0, 30).map(pub));
});

// Блокировка: аккаунт остаётся в чатах (сообщения сохраняются), но без имени, юзернеймов,
// аватарки, профиля и входа. Для всех он отображается как призрак «Аккаунт заблокирован».
app.post('/api/admin/users/:id/block', adminOnly, async (req, res) => {
    const id = Number(req.params.id);
    const users = read(F.users), u = users.find(x => x.id === id);
    if (!u || u.bot || u.fake) return res.status(404).json({ error: 'Пользователь не найден' });
    if (ADMIN_HANDLES.includes(u.handle)) return res.status(400).json({ error: 'Нельзя заблокировать администратора' });
    syncHandles(u);
    // резервная копия для разблокировки; юзернеймы остаются занятыми
    u.banBackup = { username: u.username, handle: u.handle, handles: [...u.handles], bio: u.bio || '', avatar: u.avatar || '', acc: u.acc || null, contactNames: u.contactNames || {} };
    u.banned = true;
    u.username = 'Аккаунт заблокирован';
    u.handle = '';
    u.handles = [];
    u.uListings = [];
    u.bio = '';
    u.avatar = '';
    delete u.contactNames;
    delete u.acc;
    write(F.users, users);
    // выкидываем все сессии и открытые сокеты
    const sessions = read(F.sessions);
    Object.keys(sessions).forEach(t => { if (sessions[t].uid === id) delete sessions[t]; });
    write(F.sessions, sessions);
    sockets.get(id)?.forEach(s => { try { s.close(); } catch {} });
    broadcast({ type: 'chat' });
    await persist();
    res.json({ success: true });
});

// Разблокировка: возвращаем имя, юзернеймы, био и фото из резервной копии.
// Пока аккаунт заблокирован, его юзернеймы занять нельзя (см. handleTaken).
app.post('/api/admin/users/:id/unblock', adminOnly, async (req, res) => {
    const id = Number(req.params.id);
    const users = read(F.users), u = users.find(x => x.id === id);
    if (!u || !u.banned) return res.status(404).json({ error: 'Заблокированный пользователь не найден' });
    const b = u.banBackup;
    if (b) {
        u.username = b.username; u.handle = b.handle; u.handles = b.handles;
        u.bio = b.bio; u.avatar = b.avatar;
        if (b.acc) u.acc = b.acc;
        if (b.contactNames) u.contactNames = b.contactNames;
    } else {
        // аккаунт заблокирован до появления резервной копии — даём временный юзернейм
        u.username = 'Пользователь'; u.handle = 'user' + String(u.id).slice(-6); u.handles = [u.handle];
    }
    u.uListings = [];
    delete u.banned;
    delete u.banBackup;
    write(F.users, users);
    broadcast({ type: 'chat' });
    await persist();
    res.json({ success: true });
});

// Список заблокированных с их зарезервированными юзернеймами (видно только админу)
app.get('/api/admin/banned', adminOnly, (req, res) => {
    res.json(read(F.users).filter(u => u.banned).map(u => ({
        id: u.id,
        name: (u.banBackup && u.banBackup.username) || '—',
        reserved: ((u.banBackup && u.banBackup.handles) || []).map(h => '@' + h)
    })));
});

// Полное удаление аккаунта: убирает пользователя, его сессии, личные чаты и освобождает юзернеймы.
// Сообщения в группах и каналах остаются (как в Telegram), но автор показывается как «Удалённый аккаунт».
app.delete('/api/admin/users/:id', adminOnly, async (req, res) => {
    const id = req.params.id;
    const users = read(F.users);
    const u = users.find(x => String(x.id) === id);
    if (!u) return res.status(404).json({ error: 'Пользователь не найден' });
    if (u.bot || u.fake) return res.status(400).json({ error: 'Нельзя удалить системный аккаунт' });
    if (ADMIN_HANDLES.includes(u.handle)) return res.status(400).json({ error: 'Нельзя удалить администратора' });

    // 1. Удаляем все сессии
    const sessions = read(F.sessions);
    Object.keys(sessions).forEach(t => { if (String(sessions[t].uid) === id) delete sessions[t]; });
    write(F.sessions, sessions);

    // 2. Закрываем открытые WebSocket-соединения
    sockets.get(u.id)?.forEach(ws => { try { ws.close(); } catch {} });

    // 3–9. Атомарно удаляем все данные пользователя за один проход
    const allChats = read(F.chats);
    const allMsgs  = read(F.messages);

    // ID личных чатов пользователя (удаляются целиком)
    const directIds = new Set(
        allChats.filter(c => c.type === 'direct' && (c.members || []).includes(u.id)).map(c => c.id)
    );
    // ID всех сообщений пользователя (для снятия закреплений)
    const userMsgIds = new Set(
        allMsgs.filter(m => String(m.senderId) === id).map(m => m.id)
    );

    // Чаты: удаляем личные, из остальных убираем членство и чистим закреплённые сообщения
    const newChats = allChats
        .filter(c => !directIds.has(c.id))
        .map(c => {
            if (!(c.members || []).includes(u.id) && !c.pin && !c.pins) return c;
            const nc = { ...c };
            if ((nc.members || []).includes(u.id)) {
                nc.members = nc.members.filter(x => x !== u.id);
                if (nc.reads)   { nc.reads   = { ...nc.reads };   delete nc.reads[u.id]; }
                if (nc.cleared) { nc.cleared = { ...nc.cleared }; delete nc.cleared[u.id]; }
            }
            if (nc.pin  && userMsgIds.has(nc.pin.id))  delete nc.pin;
            if (nc.pins) nc.pins = nc.pins.filter(pid => !userMsgIds.has(pid));
            return nc;
        });

    // Сообщения: удаляем личные чаты + все сообщения пользователя
    const newMsgs = allMsgs.filter(m => !directIds.has(m.chatId) && String(m.senderId) !== id);

    write(F.chats,    newChats);
    write(F.messages, newMsgs);
    const blksRaw = read(F.blocks);
    const newBlks = {};
    for (const [uid, ids] of Object.entries(blksRaw)) {
        if (String(uid) === String(u.id)) continue;
        const filtered = (Array.isArray(ids) ? ids : []).filter(id => String(id) !== String(u.id));
        if (filtered.length) newBlks[uid] = filtered;
    }
    write(F.blocks, newBlks);
    write(F.gifts,    read(F.gifts).filter(g => g.ownerId !== u.id && g.senderId !== u.id));
    write(F.users,    users.filter(x => x.id !== u.id));

    // 10. Уведомляем всех об изменении чатов
    broadcast({ type: 'chat' });
    await persist();
    res.json({ success: true, deleted: u.username || u.id });
});


// Выдача / снятие верификации (галочки) администратором
app.post('/api/admin/users/:id/verify', adminOnly, async (req, res) => {
    const users = read(F.users);
    const u = users.find(x => String(x.id) === req.params.id);
    if (!u) return res.status(404).json({ error: 'Пользователь не найден' });
    if (VERIFIED.has(u.handle)) {
        VERIFIED.delete(u.handle);
    } else {
        VERIFIED.add(u.handle);
    }
    broadcast({ type: 'chat' });
    res.json({ success: true, verified: VERIFIED.has(u.handle), handle: u.handle });
});

// ---------- Подписка SAIMONPREMIYM ----------
// Тарифы: цена в Mars. Подписка дарит цвет ника (градиент) и значок 💎 в профиле.
const PREMIUM_PLANS = {
    day:     { price: 50,    ms: 1 * 86400000 },
    month:   { price: 1200,  ms: 30 * 86400000 },
    year:    { price: 15000, ms: 365 * 86400000 },
    forever: { price: 30000, ms: null }
};
function premiumOn(u) { return !!u.premium && (u.premium === 'forever' || Date.parse(u.premium) > Date.now()); }
const hexOk = c => typeof c === 'string' && /^#[0-9a-f]{6}$/i.test(c);

// Сообщение в личном чате о подаренной подписке (получатель видит «Вам подарили», покупатель — «Вы подарили»)
function premMessage(from, to, planKey) {
    const chats = read(F.chats), id = directId(from, to);
    let chat = chats.find(c => c.id === id);
    if (!chat) {
        chat = { id, type: 'direct', members: [from, to], reads: {}, createdAt: new Date().toISOString() };
        chats.push(chat);
        write(F.chats, chats);
    }
    const msg = { id: crypto.randomUUID(), chatId: id, senderId: from, text: '', prem: { plan: planKey }, timestamp: new Date().toISOString() };
    const msgs = read(F.messages);
    msgs.push(msg);
    write(F.messages, msgs);
    sendTo(chat.members, { type: 'message', data: msg });
    notifyMessage(chat, msg, '💎 Вам подарили подписку SAIMONPREMIYM');
}

// Купить себе или подарить: списываем Mars у покупателя, продлеваем подписку получателю
app.post('/api/premium/buy', async (req, res) => {
    const me = req.uid, plan = PREMIUM_PLANS[req.body.plan];
    if (!plan) return res.status(400).json({ error: 'Неизвестный тариф' });
    const users = read(F.users);
    const buyer = users.find(u => u.id === me);
    const toId = req.body.toId ? Number(req.body.toId) : me;
    const target = users.find(u => u.id === toId);
    if (!buyer || !target || target.banned || target.bot || target.fake)
        return res.status(400).json({ error: 'Получатель не найден' });
    if (toId !== me && blockedEither(me, toId))
        return res.status(400).json({ error: 'Нельзя подарить: один из вас заблокировал другого' });
    if (!isUnlimited(buyer) && (buyer.mars || 0) < plan.price)
        return res.status(400).json({ error: `Не хватает Mars: нужно ${plan.price}, у вас ${buyer.mars || 0}` });

    if (!isUnlimited(buyer)) buyer.mars -= plan.price;
    if (toId !== me) premMessage(me, toId, req.body.plan);
    if (target.premium === 'forever') { /* навсегда уже есть */ }
    else if (plan.ms === null) target.premium = 'forever';
    else {
        const base = premiumOn(target) ? Date.parse(target.premium) : Date.now();
        target.premium = new Date(base + plan.ms).toISOString();
    }
    write(F.users, users);
    sendTo([me], { type: 'wallet', data: walletOf(buyer) });
    broadcast({ type: 'chat' });
    await persist();
    res.json({ success: true, premium: target.premium, ...walletOf(buyer) });
});

// Цвет ника: градиент из двух цветов, только для активной подписки
app.put('/api/premium/nick', async (req, res) => {
    const users = read(F.users), u = users.find(x => x.id === req.uid);
    if (!u || !premiumOn(u)) return res.status(403).json({ error: 'Нужна подписка SAIMONPREMIYM' });
    if (req.body.reset) delete u.nickGrad;
    else {
        if (!hexOk(req.body.c1) || !hexOk(req.body.c2)) return res.status(400).json({ error: 'Некорректный цвет' });
        u.nickGrad = [req.body.c1, req.body.c2];
    }
    write(F.users, users);
    broadcast({ type: 'chat' });
    await persist();
    res.json({ success: true, nickGrad: u.nickGrad || null });
});

// Переливающаяся рамка (только для премиум-пользователей)
