// ---------- WebSocket ----------
wss.on('connection', ws => {
    let uid = null;
    ws.isAlive = true;
    ws.on('pong', () => { ws.isAlive = true; });
    ws.on('error', () => {}); // ошибка одного клиента не должна ронять сервер

    ws.on('message', raw => {
        try {
            const m = JSON.parse(raw);

            if (m.type === 'connect') {
                const sess = read(F.sessions)[m.token];
                if (!sess) { ws.send(JSON.stringify({ type: 'auth', data: { ok: false } })); return ws.close(); }
                uid = sess.uid;
                ws.active = m.active !== false;
                if (!sockets.has(uid)) sockets.set(uid, new Set());
                sockets.get(uid).add(ws);
                broadcast({ type: 'presence', data: { userId: uid, online: true } });
                const u = read(F.users).find(x => x.id === uid);
                if (u) ws.send(JSON.stringify({ type: 'wallet', data: walletOf(u) }));
                return;
            }
            if (!uid) return;
            if (m.type === 'active') { ws.active = !!m.active; return; } // вкладка открыта и видна — идёт время для Mars

            const chats = read(F.chats);
            const chat = chats.find(c => String(c.id) === String(m.chatId));
            if (!chat || !chat.members.includes(uid)) return;

            if (m.type === 'message') {
                if (chat.type === 'channel' && chat.creator !== uid && !chat.open) return; // в канал пишет только автор (в текстовом — все)
                if (chat.type === 'direct') {
                    const other = chat.members.find(i => i !== uid);
                    if (other === BOT_ID) return; // с ботом общаются кнопками
                    if (other && blockedEither(uid, other)) {
                        return ws.send(JSON.stringify({ type: 'error', data: { cid: m.cid, text: iBlocked(uid, other) ? 'Вы заблокировали этого пользователя' : 'Не удалось отправить сообщение' } }));
                    }
                }
                const text = String(m.text || '').trim().slice(0, 4000);
                let media;
                if (m.media && fileOk(m.media.url)) {
                    media = { kind: kindOf(m.media.url), url: m.media.url };
                    const w = Number(m.media.w), h = Number(m.media.h);
                    if (w > 0 && h > 0 && w < 20000 && h < 20000) { media.w = Math.round(w); media.h = Math.round(h); }
                    const dur = Number(m.media.dur);
                    if (media.kind === 'voice' && dur > 0 && dur < 3600) media.dur = Math.round(dur);
                }
                if (!text && !media) return;

                // Ответ на сообщение: сохраняем снапшот оригинала (переживёт его удаление)
                let reply;
                if (m.reply && typeof m.reply === 'object') {
                    const orig = read(F.messages).find(x => x.id === String(m.reply.id || '') && x.chatId === chat.id);
                    if (orig) {
                        const u = read(F.users).find(x => x.id === orig.senderId);
                        reply = { id: orig.id, name: u ? u.username : 'Удалённый аккаунт', ...(u ? { handle: u.handle } : {}),
                            text: String(orig.text || '').slice(0, 120), mk: orig.media ? orig.media.kind : (orig.gift ? 'gift' : '') };
                    }
                }
                // Пересылка: помечаем, от кого оригинал
                let fwd;
                if (m.fwd && typeof m.fwd === 'object') {
                    const u = read(F.users).find(x => x.id === Number(m.fwd.from));
                    if (u) fwd = { from: u.id, name: u.username, handle: u.handle };
                }

                const msg = {
                    id: crypto.randomUUID(), chatId: chat.id, senderId: uid, text,
                    ...(media && { media }), ...(reply && { reply }), ...(fwd && { fwd }), timestamp: new Date().toISOString()
                };
                if (chat.type === 'channel' && !chat.open) { msg.viewers = [uid]; msg.fv = rollFv(fakeInChannel(chat, read(F.users))); }
                const msgs = read(F.messages);
                msgs.push(msg);
                write(F.messages, msgs);
                sendTo(chat.members, { type: 'message', data: outMsg(msg, chat), cid: m.cid ? String(m.cid).slice(0, 40) : undefined }); // только участникам чата; cid — чтобы отправитель заменил своё временное
                notifyMessage(chat, msg);

            } else if (m.type === 'read') {
                if (chat.type === 'channel' && !chat.open) markViews(chat, uid);
                // Помечаем прочитанным всё до последнего сообщения включительно
                const last = read(F.messages).filter(x => x.chatId === chat.id).pop();
                const at = last ? last.timestamp : '';
                chat.reads = chat.reads || {};
                if (!at || (chat.reads[uid] || '') >= at) return;
                chat.reads[uid] = at;
                write(F.chats, chats);
                sendTo(chat.members, { type: 'read', data: { chatId: chat.id, userId: uid, at } });

            } else if (m.type === 'typing') {
                if (chat.type === 'channel') return;
                if (chat.type === 'direct' && blockedEither(uid, chat.members.find(i => i !== uid))) return;
                sendTo(chat.members, { type: 'typing', data: { chatId: chat.id, userId: uid } }, ws);
            }
            // ── Казино ──────────────────────────────────────────
            if (m.type === 'casino_subscribe') {
                casinoClients.add(ws);
                ws.send(JSON.stringify({
                    type: 'casino_crash_waiting',
                    roundId: CRASH_STATE.roundId,
                    history: CRASH_STATE.history,
                    countdown: 5,
                    phase: CRASH_STATE.phase,
                    multiplier: +CRASH_STATE.multiplier.toFixed(2),
                }));
                return;
            }

        } catch (err) {
            console.error('WS error:', err);
        }
    });

    ws.on('close', () => {
        casinoClients.delete(ws);
        if (!uid || !sockets.has(uid)) return;
        sockets.get(uid).delete(ws);
        if (!sockets.get(uid).size) {
            sockets.delete(uid);
            broadcast({ type: 'presence', data: { userId: uid, online: false } });
        }
    });
});

// ═══════════════════════════════════════════════════════════════════════════
// CASINO
// ═══════════════════════════════════════════════════════════════════════════

app.get('/casino', (req, res) => res.sendFile(path.join(__dirname, 'casino.html')));

const casinoClients = new Set();

const CRASH_STATE = {
    phase: 'waiting',
    bets: new Map(),
    multiplier: 1.00,
    crashAt: 1.00,
    startAt: 0,
    history: [],
    roundId: 0,
};

function genCrashPoint() {
    const r = Math.random();
    if (r < 0.0476) return 1.00;
    return Math.floor(100 / (1 - r) * 0.95) / 100;
}

function broadcastCasino(data) {
    const msg = JSON.stringify(data);
    for (const ws of casinoClients) {
        if (ws.readyState === 1) ws.send(msg);
    }
}

let crashTicker = null;

function crashRound() {
    CRASH_STATE.phase = 'waiting';
    CRASH_STATE.bets.clear();
    CRASH_STATE.multiplier = 1.00;
    CRASH_STATE.crashAt = genCrashPoint();
    CRASH_STATE.roundId++;
    broadcastCasino({ type: 'casino_crash_waiting', roundId: CRASH_STATE.roundId, history: CRASH_STATE.history, countdown: 5 });
    setTimeout(() => {
        if (CRASH_STATE.phase !== 'waiting') return;
        CRASH_STATE.phase = 'running';
        CRASH_STATE.startAt = Date.now();
        broadcastCasino({ type: 'casino_crash_start', roundId: CRASH_STATE.roundId });
        crashTicker = setInterval(() => {
            const t = (Date.now() - CRASH_STATE.startAt) / 1000;
            const m = Math.floor(Math.pow(Math.E, 0.06 * t) * 100) / 100;
            CRASH_STATE.multiplier = m;
            if (m >= CRASH_STATE.crashAt) {
                clearInterval(crashTicker);
                CRASH_STATE.phase = 'crashed';
                CRASH_STATE.history.unshift(+CRASH_STATE.crashAt.toFixed(2));
                if (CRASH_STATE.history.length > 15) CRASH_STATE.history.pop();
                broadcastCasino({ type: 'casino_crash_end', crashAt: +CRASH_STATE.crashAt.toFixed(2), roundId: CRASH_STATE.roundId });
                setTimeout(crashRound, 5000);
            } else {
                broadcastCasino({ type: 'casino_crash_tick', multiplier: +m.toFixed(2), roundId: CRASH_STATE.roundId });
            }
        }, 100);
    }, 5000);
}

