        bet.cashoutMultiplier = m;
        const users = read(F.users);
        const user = users.find(u => u.id === me);
        user.mars = (user.mars || 0) + won;
        write(F.users, users);
        sendTo([me], { type: 'wallet', data: walletOf(user) });
        broadcastCasino({ type: 'casino_crash_cashout', userId: me, multiplier: +m.toFixed(2), amount: won });
        await persist();
        res.json({ success: true, won, multiplier: +m.toFixed(2), mars: user.mars });
