const RARITY_UP = { common: 'rare', rare: 'epic', epic: 'legendary' };
const UPGRADE_FEE = { common: 50, rare: 200, epic: 500 };

app.post('/api/casino/nft-upgrade', async (req, res) => {
    try {
        const me = req.uid;
        const ids = req.body.ids;
        if (!Array.isArray(ids) || ids.length !== 3) return res.status(400).json({ error: 'Выберите ровно 3 НФТ' });
        const gifts = read(F.gifts);
        const users = read(F.users);
        const user = users.find(u => u.id === me);
        if (!user) return res.status(400).json({ error: 'Пользователь не найден' });
        const selected = ids.map(id => gifts.find(g => g.id === id && g.ownerId === me));
        if (selected.some(g => !g)) return res.status(400).json({ error: 'НФТ не найден или не ваш' });
        const kinds = selected.map(g => g.kind);
        if (new Set(kinds).size !== 1) return res.status(400).json({ error: 'НФТ должны быть одного типа' });
        const kind = kinds[0];
        const item = CATALOG.find(c => c.kind === kind);
        if (!item) return res.status(400).json({ error: 'Неизвестный тип НФТ' });
        const nextRarity = RARITY_UP[item.rarity];
        if (!nextRarity) return res.status(400).json({ error: 'Легендарный нельзя улучшить' });
        const fee = UPGRADE_FEE[item.rarity] || 0;
        if ((user.mars || 0) < fee) return res.status(400).json({ error: `Нужно ${fee} Mars для улучшения` });
        const nextItems = CATALOG.filter(c => c.rarity === nextRarity);
        if (!nextItems.length) return res.status(400).json({ error: 'Нет НФТ следующей редкости' });
        const nextItem = nextItems[Math.floor(Math.random() * nextItems.length)];
        const minted = gifts.filter(g => g.kind === nextItem.kind).length;
        if (minted >= nextItem.supply) return res.status(400).json({ error: 'Следующий НФТ распродан' });
        user.mars -= fee;
        for (const g of selected) {
            const idx = gifts.findIndex(x => x.id === g.id);
            if (idx !== -1) gifts.splice(idx, 1);
        }
        const newGift = {
            id: 'k_' + crypto.randomUUID(), kind: nextItem.kind, serial: minted + 1,
            ownerId: me, channelId: null, fromId: me, price: nextItem.price,
            at: new Date().toISOString(), bd: pickBackdrop(user).id, pt: pickPattern().id, note: 'Апгрейд в казино',
        };
        gifts.push(newGift);
        write(F.gifts, gifts);
        write(F.users, users);
        sendTo([me], { type: 'wallet', data: walletOf(user) });
        await persist();
        res.json({ success: true, gift: giftOut(newGift, users), mars: user.mars });
    } catch (e) { console.error('nft-upgrade:', e); res.status(500).json({ error: e.message }); }
});

